<!-- ===== JAVASCRIPT ===== -->
<script>
// --- Mega Menu Hover ---
document.querySelectorAll('.nav-item').forEach(item => {
  item.addEventListener('mouseenter', () => item.classList.add('active'));
  item.addEventListener('mouseleave', () => item.classList.remove('active'));
});

// --- Mobile Menu Toggle ---
document.getElementById('mobileMenuBtn').addEventListener('click', () => {
  document.getElementById('mobileMenu').classList.toggle('hidden');
});

// --- Mobile Sub-Menu Toggles ---
document.querySelectorAll('.mobile-sub-toggle').forEach(toggle => {
  toggle.addEventListener('click', function() {
    const target = document.getElementById(this.dataset.mobileMenu);
    if (target) {
      target.classList.toggle('hidden');
      const arrow = this.querySelector('svg');
      if (arrow) {
        arrow.style.transform = target.classList.contains('hidden') ? '' : 'rotate(180deg)';
      }
    }
  });
});

// --- Recommended Reads Tabs ---
document.querySelectorAll('#recTabs .tab-btn').forEach(btn => {
  btn.addEventListener('click', function() {
    document.querySelectorAll('#recTabs .tab-btn').forEach(b => b.classList.remove('active'));
    this.classList.add('active');

    const tabId = 'tab-' + this.dataset.tab;
    document.querySelectorAll('.tab-content').forEach(content => content.classList.remove('active'));
    document.getElementById(tabId).classList.add('active');
  });
});

// --- Health Topics Carousel ---
const carousel = document.getElementById('topicsCarousel');
const cardWidth = 184; // w-40 (160px) + gap-5 (20px) + some padding

document.getElementById('carouselNext').addEventListener('click', () => {
  carousel.scrollBy({ left: cardWidth * 2, behavior: 'smooth' });
});

document.getElementById('carouselPrev').addEventListener('click', () => {
  carousel.scrollBy({ left: -cardWidth * 2, behavior: 'smooth' });
});

// --- Newsletter Form ---
function showToast(message) {
  const toast = document.getElementById('toast');
  toast.textContent = message;
  toast.classList.add('show');
  setTimeout(() => toast.classList.remove('show'), 3000);
}

document.getElementById('newsletterForm').addEventListener('submit', function(e) {
  e.preventDefault();
  const email = document.getElementById('newsletterEmail').value;
  if (email) {
    showToast('Welcome aboard! Check your inbox for confirmation.');
    document.getElementById('newsletterEmail').value = '';
  }
});

document.getElementById('footerNewsletter').addEventListener('submit', function(e) {
  e.preventDefault();
  const email = document.getElementById('footerEmail').value;
  if (email) {
    showToast('You\'re signed up! Look for our next edition in your inbox.');
    document.getElementById('footerEmail').value = '';
  }
});

// --- Close mega menu when clicking outside ---
document.addEventListener('click', function(e) {
  if (!e.target.closest('.nav-item')) {
    document.querySelectorAll('.nav-item').forEach(item => item.classList.remove('active'));
  }
});
</script>

</body>
</html>
